def add_photo_and_build(fname, nums):
    c = open(fname).read()
    for num in nums:
        # 1. photo: insert before the door's component-card diagram (the 2nd .diagram in that door)
        m = list(re.finditer(r'num:' + str(num) + r',[\s\S]*?<div class="verse">', c))
        assert m, f"door {num} not found"
        seg = m[0]
        # find 2nd diagram start inside segment
        dg_positions = [x.start() for x in re.finditer(r'<div class="diagram">', seg.group(0))]
        if len(dg_positions) >= 2:
            abs_pos = seg.start(0) + dg_positions[1]
            fn, cap = PHOTO[num]
            c = c[:abs_pos] + photo_block(fn, cap) + '\n' + c[abs_pos:]
        # 2. build-thread: insert before secret-box
        m2 = list(re.finditer(r'num:' + str(num) + r',[\s\S]*?(<div class="secret-box">)', c))
        assert m2, f"door {num} secret-box not found"
        title, body, _ = BUILD[num]
        block = f'\n<div class="callout build"><span class="co-icon">🛠️</span><div><strong>নির্মাণ-পর্ব {num} — {title}:</strong> {body}</div></div>\n'
        c = c[:m2[0].start(1)] + block + c[m2[0].start(1):]
    open(fname, 'w').write(c)
    print(f"{fname}: photos+build-blocks for doors {nums}")

add_photo_and_build('doors-1-4.js', [1, 2, 3, 4])
add_photo_and_build('doors-5-8.js', [5, 6, 7, 8])
add_photo_and_build('doors-9-12.js', [9, 10, 11, 12])
add_photo_and_build('doors-13-16.js', [13, 14, 15, 16])
